using J=nlohmann::json;namespace fs=std::filesystem;using Ns=std::int64_t;
void require(bool yes,const char* why){if(!yes)throw std::runtime_error(why);}
J parse(std::istream& input){std::vector<std::set<std::string>> keys;return J::parse(input,[&](int depth,J::parse_event_t e,J& v){require(depth<=64,"JSON depth");if(e==J::parse_event_t::object_start)keys.emplace_back();if(e==J::parse_event_t::key)require(!keys.empty()&&keys.back().insert(v.get<std::string>()).second,"duplicate key");if(e==J::parse_event_t::object_end)keys.pop_back();return true;});}
J bind(const fs::path& path,std::uint64_t cap){return {{"path",fs::canonical(path).string()},{"bytes",fs::file_size(path)},{"sha256",pas::evidence::sha256(path,cap)}};}
J read(const fs::path& path,std::uint64_t cap){require(fs::file_size(path)<=cap,"byte bound");std::ifstream f(path);require(bool(f),"input read");return parse(f);}
J dist(std::vector<double> v){if(v.empty())return {{"n",0}};std::sort(v.begin(),v.end());auto q=[&](double p){const double at=(v.size()-1)*p;const auto lo=std::size_t(at),hi=std::min(lo+1,v.size()-1);return v[lo]+(v[hi]-v[lo])*(at-lo);};return {{"n",v.size()},{"p50",q(.5)},{"p95",q(.95)},{"p99",q(.99)},{"max",v.back()},{"jitter_p95_minus_p5",q(.95)-q(.05)}};}
void equal(const J& a,const J& b){require(a.at("n")==b.at("n"),"distribution n");for(const auto* key:{"p50","p95","p99","max","jitter_p95_minus_p5"})require(std::abs(a.at(key).get<double>()-b.at(key).get<double>())<1e-7,"reported/raw quantile");}
int main(int argc,char** argv){try{
 require(argc==4&&!fs::exists(argv[3]),"usage pinned-input input-sha fresh-output");
 const fs::path input=fs::canonical(argv[1]);const auto ib=bind(input,1048576);require(ib.at("sha256")==argv[2],"input external pin");const auto in=read(input,1048576);require(in.at("schema")=="pas.dense-noise-diagnosis-input.v1"&&in.at("runs").size()==4,"exact dense four runs");
 J outputs=J::array(),all_bindings=J::array();std::set<fs::path> report_paths;std::set<std::string> process_ids;
 for(const auto& entry:in.at("runs")){
  const fs::path report=fs::canonical(entry.at("path").get<std::string>()),attempts=report.string()+".attempts.json",journal=report.string()+".journal.jsonl";
  require(report_paths.insert(report).second,"distinct raw reports");const auto rb=bind(report,1048576),ab=bind(attempts,16ull*1048576),jb=bind(journal,1073741824);require(rb==entry,"pinned raw report binding");all_bindings.push_back(rb);all_bindings.push_back(ab);all_bindings.push_back(jb);
  const auto r=read(report,1048576),a=read(attempts,16ull*1048576);require(r.at("scene")=="dense"&&r.at("mode")=="A"&&r.at("requested")==2560&&r.at("cadence_ms")==20&&r.at("safe").get<bool>()&&!r.at("supervisor_stopped").get<bool>()&&r.at("release_verified").get<bool>()&&r.at("first_owner_failure").is_null(),"successful unchanged dense contract");
  require(r.at("provenance").at("source_commit")==in.at("source_commit")&&r.at("provenance").at("campaign_sha256")==in.at("campaign_sha256"),"same source/campaign");const auto& p=r.at("provenance").at("process");require(process_ids.insert(p.at("pid").dump()+":"+p.at("creation_filetime").dump()).second,"distinct native process");require(a.is_array()&&a.size()==2560,"all attempts");
  std::map<std::uint64_t,J> scenes,outcomes;std::size_t rows=0;std::uint64_t bytes=0;std::ifstream f(journal);std::string line;
  while(std::getline(f,line)){require(++rows<=65536&&line.size()<=262144&&(bytes+=line.size()+1)<=1073741824,"journal capacity");std::istringstream is(line);const auto e=parse(is);const std::string event=e.at("event");if(event=="current_observer_scene"){const auto& s=e.at("scene");const auto frame=s.at("frame_sequence").get<std::uint64_t>();require(frame<=2560&&scenes.size()<2560&&scenes.emplace(frame,J{{"recognition_start",s.at("recognition_start_ns")},{"recognition_end",s.at("recognition_end_ns")},{"targets",s.at("targets").size()},{"lines",s.at("lines").size()}}).second,"observer scene identity");}if(event=="owner_step_outcome"){const auto frame=e.at("source_frame").get<std::uint64_t>();require(frame<=2560&&outcomes.size()<2560&&outcomes.emplace(frame,e).second,"owner outcome identity");}}
  require(rows==r.at("journal_records"),"journal full rows");std::vector<double> total,observer,hook,owner,remainder,waiting,gap;std::vector<J> ranked;std::size_t owned=0,measured=0;
  for(std::size_t i=0;i<a.size();++i){const auto& sample=a[i];require(sample.at("attempt")==i+1,"attempt order");if(!sample.at("owned").get<bool>())continue;++owned;require(scenes.contains(i+1)&&outcomes.contains(i+1),"complete scene/outcome/attempt join");if(i<256)continue;++measured;const auto& s=scenes.at(i+1);const auto& o=outcomes.at(i+1);const Ns capture=sample.at("capture"),end=sample.at("owner_complete"),obs=sample.at("observer_ns"),h=sample.at("hook_ns"),own=sample.at("owner_ns"),start=s.at("recognition_start"),cg=o.at("checkpoint_max_gap_ns");require(end>=capture&&start>=capture&&obs>=0&&h>=0&&own>=0&&cg>=0,"QPC durations");const Ns residual=end-capture-obs-h-own;require(residual>=0,"nonnegative same-frame residual");total.push_back((end-capture)/1e6);observer.push_back(obs/1e6);hook.push_back(h/1e6);owner.push_back(own/1e6);remainder.push_back(residual/1e6);waiting.push_back((start-capture)/1e6);gap.push_back(cg/1e6);ranked.push_back({{"attempt",i+1},{"capture_to_owner_ms",(end-capture)/1e6},{"observer_ms",obs/1e6},{"hook_ms",h/1e6},{"owner_ms",own/1e6},{"unmetered_elapsed_ms",residual/1e6},{"capture_to_observer_start_ms",(start-capture)/1e6},{"checkpoint_max_gap_ms",cg/1e6},{"checkpoint_calls",o.at("checkpoint_calls")},{"outcome",o.at("outcome")},{"targets",s.at("targets")},{"lines",s.at("lines")}});}
  require(owned==r.at("owner_seen")&&measured==r.at("measurement").at("owner_seen"),"owned full/measured denominators");equal(dist(total),r.at("measurement").at("capture_to_owner_ms"));equal(dist(observer),r.at("measurement").at("observer_ms"));equal(dist(hook),r.at("measurement").at("hook_ms"));equal(dist(owner),r.at("measurement").at("owner_ms"));std::sort(ranked.begin(),ranked.end(),[](const J& x,const J& y){return x.at("capture_to_owner_ms").get<double>()>y.at("capture_to_owner_ms").get<double>();});require(ranked.size()>=32,"tail denominator");J top=J::array();for(std::size_t i=0;i<32;++i)top.push_back(ranked[i]);
  outputs.push_back({{"report",rb},{"full_owned",owned},{"measured_owned",measured},{"capture_to_owner_ms",dist(total)},{"observer_ms",dist(observer)},{"hook_ms",dist(hook)},{"owner_ms",dist(owner)},{"unmetered_elapsed_ms",dist(remainder)},{"capture_to_observer_start_ms",dist(waiting)},{"checkpoint_max_gap_ms",dist(gap)},{"slowest_32_same_frame_components",top},{"journal_rows",rows}});
 }
 for(const auto& b:all_bindings)require(bind(b.at("path").get<std::string>(),1073741824)==b,"input changed");require(bind(input,1048576)==ib,"manifest changed");J out={{"schema","pas.dense-noise-raw-diagnosis.v1"},{"input",ib},{"raw_bindings",all_bindings},{"runs",outputs},{"qualification",false},{"device_operations",0},{"scope","same-frame elapsed components; residual includes unmetered logging/copy/wait/scheduling, not proven CPU or OS cause; no stage p99 summation"}};std::ofstream output(argv[3]);output<<out.dump(2)<<'\n';require(bool(output),"write");std::cout<<"joined dense runs=4\n";return 0;
 }catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 2;}}
